const esc = value => String(value).replace(/[&<>\"]/g, char => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[char]));
const brand = `<a class="brand-link" href="${affiliate}" target="_blank" rel="sponsored noopener noreferrer">Higgsfield</a>`;
const rich = value => esc(String(value).replace(/\[\[Higgsfield\]\]|Higgsfield/g, "__HIGGSFIELD_BRAND__")).replaceAll("__HIGGSFIELD_BRAND__", brand);
const urlFor = code => `${base}/${code === "en" ? "" : `${code}/`}partners/higgsfield.html`;
const hrefFor = code => `/${code === "en" ? "" : `${code}/`}partners/higgsfield.html`;

function expandedCopy(code) {
  if (copy[code]) return copy[code];
  const t = fallbackTranslations[code];
  const g = generic[code];
  const en = copy.en;
  return {
    ...en,
    ...localizedDetails[code],
    title: `Higgsfield AI Video Generator: ${t[7]}, ${t[8]}`,
    description: g.description,
    eyebrow: t[0], headline: t[1], lead: t[2], start: t[3], disclosure: g.disclosure,
    introTitle: t[4], intro: g.body[0], workflowTitle: t[5], modelsTitle: t[6], models: g.body[1],
    resolutionTitle: t[7], resolution: g.body[2], musicTitle: t[8], music: g.body[3], useTitle: t[9],
    chooseTitle: t[10], faqTitle: t[11], finalTitle: t[12], finalCta: t[13]
  };
}

